import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-molecular-biology-transcription-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`What does the 5' cap accomplish?`]: {
    question: r`A yeast strain with a temperature-sensitive capping enzyme is shifted to the restrictive temperature. Most new mRNAs are degraded or stay in the nucleus. For the few uncapped transcripts that do reach the cytoplasm, which further defect is expected?`,
    options: [r`Failure of the ribosome to remove their introns`, r`Translation that begins at the poly-A tail instead`, r`Poor recruitment of ribosomes to begin translation`, r`Loss of the stop codon from the reading frame`],
    correctAnswer: 2,
    explanation: r`The cap is the feature the translation initiation machinery recognizes, so an uncapped mRNA recruits ribosomes poorly, on top of being exposed to exonucleases and exported badly. Ribosomes never remove introns, translation does not start at the tail, and the cap has nothing to do with the stop codon.`,
  },
  [r`Why do prokaryotes lack mRNA processing?`]: {
    question: r`An electron micrograph of E. coli shows ribosomes already attached to an mRNA whose 3' end is still being made by RNA polymerase on the DNA. Why is this picture never seen for a gene in a human nucleus?`,
    options: [r`The nuclear envelope keeps ribosomes away from new RNA`, r`Human ribosomes cannot bind an RNA that has a 5' cap`, r`Human RNA polymerase makes RNA from protein templates`, r`Human mRNA is translated starting from its 3' end`],
    correctAnswer: 0,
    explanation: r`Bacteria have no nucleus, so translation starts on a transcript that is still being made, which leaves no time or place for processing. In eukaryotes the envelope separates the two steps, and the transcript is capped, tailed and spliced before export. Ribosomes need the cap rather than avoid it, RNA polymerase copies DNA, and translation always runs 5' to 3'.`,
  },
  [r`What enzyme performs transcription and where does it bind?`]: {
    question: r`A researcher moves the intact coding region of a eukaryotic gene to a chromosomal site that has no promoter upstream of it. What is the most likely result?`,
    options: [r`DNA polymerase transcribes the gene in its place`, r`Ribosomes bind the DNA and begin at the ATG codon`, r`RNA polymerase starts as usual at the stop codon`, r`RNA polymerase fails to bind, so little RNA is made`],
    correctAnswer: 3,
    explanation: r`RNA polymerase is brought to a gene by its promoter, which lies upstream of the coding region, so without a promoter almost no transcript is made. DNA polymerase replicates DNA and does not transcribe, ribosomes bind mRNA and not DNA, and the polymerase does not find genes by their codons.`,
  },
  [r`List the three eukaryotic mRNA processing steps.`]: {
    question: r`A nuclear RNA has a 7-methylguanosine at its 5' end and all of its introns removed, but it has not yet been exported. Which processing step is still missing?`,
    options: [r`Addition of a poly-A tail to the 3' end`, r`Addition of a poly-A tail to the 5' end`, r`Removal of exons by the spliceosome`, r`Attachment of CCA to the 3' end`],
    correctAnswer: 0,
    explanation: r`The three processing steps are the 5' cap, splicing of introns, and the 3' poly-A tail, so the tail is the one not yet done. The tail goes on the 3' end, not the 5' end. The spliceosome removes introns and keeps exons, and a CCA end belongs to tRNA.`,
  },
  [r`How does alternative splicing expand the proteome?`]: {
    question: r`A gene has exons 1 to 5. Muscle mRNA from this gene contains exons 1, 2, 3 and 5. Neuron mRNA contains exons 1, 2, 4 and 5. The genomic DNA is identical in both tissues, and the two proteins differ in one domain. What explains this?`,
    options: [r`Two separate genes were transcribed in each tissue`, r`One pre-mRNA was spliced in two different patterns`, r`The DNA was rearranged differently in each tissue`, r`One mRNA was translated in two reading frames`],
    correctAnswer: 1,
    explanation: r`The same pre-mRNA can have different combinations of exons joined, giving protein isoforms that share most of their sequence but differ in one region. The stem says there is one gene and identical DNA, which rules out two genes and DNA rearrangement. Two reading frames would give unrelated proteins, not a change in one domain.`,
  },
  [r`How do enhancers differ from promoters?`]: {
    question: r`Element X lies 30 bp upstream of a gene's start site and stops working when it is inverted or moved 3 kb away. Element Y lies inside an intron 10 kb downstream and still stimulates transcription after it is flipped. How should X and Y be classified?`,
    options: [r`X is an enhancer and Y is a promoter`, r`X is a promoter and Y is an enhancer`, r`X and Y are both promoter elements`, r`X is an operator and Y is a promoter`],
    correctAnswer: 1,
    explanation: r`A promoter must sit just upstream in a fixed orientation because it positions the polymerase, while an enhancer works at a distance and in either orientation through DNA looping. Swapping the labels reverses these properties. Y cannot be a promoter element because it is far downstream, and operators are bacterial repressor sites.`,
  },
  [r`Which sequences does the spliceosome recognize, and what intermediate does splicing form?`]: {
    question: r`RNA isolated from human nuclei includes a molecule shaped like a loop with a short tail. It has no free 5' end and begins with GU at the position joined into the loop. What is this molecule?`,
    options: [r`A pair of ligated exons awaiting nuclear export`, r`An excised exon joined at its poly-A tail`, r`An excised intron joined at its branch adenosine`, r`A capped pre-mRNA folded at its 5' end`],
    correctAnswer: 2,
    explanation: r`During splicing the branch-point adenosine attacks the 5' splice site, so the GU end of the intron becomes joined to the branch A and the intron is released as a lariat. Ligated exons are linear, exons are not excised, and a cap does not create a loop.`,
  },
  [r`Which DNA strand is read, and what is the resulting RNA identical to?`]: {
    question: r`The coding (sense) strand of a gene segment reads 5'-ATGGCA-3'. What is the sequence of the mRNA made from this segment?`,
    options: [r`5'-UACCGU-3'`, r`5'-UGCCAU-3'`, r`5'-AUGGCA-3'`, r`5'-ACGGUA-3'`],
    correctAnswer: 2,
    explanation: r`The mRNA is copied from the template strand, so it matches the coding strand with U in place of T: 5'-AUGGCA-3'. 5'-UACCGU-3' is the complement written without reversing direction, 5'-UGCCAU-3' is the reverse complement (the template in RNA form), and 5'-ACGGUA-3' is the coding strand read backward.`,
  },
  [r`Eukaryotic mRNA gets a {{c1::5' cap}}, a {{c2::poly-A tail}}, and has its {{c3::introns}} spliced out.`]: {
    question: r`A researcher puts the genomic copy of a human gene into E. coli behind a bacterial promoter. A long transcript is made, but the protein is the wrong length and has no activity. What best explains the failure?`,
    options: [r`Bacteria cannot transcribe any human DNA`, r`Bacteria cannot splice out the gene's introns`, r`Bacteria remove the gene's exons too early`, r`Bacteria add a poly-A tail to the 5' end`],
    correctAnswer: 1,
    explanation: r`Eukaryotic transcripts must have their introns spliced out before translation, and bacteria have no spliceosome, so the introns are translated as if they were coding sequence. The transcript was made, so transcription is not the problem. Bacteria do not remove exons or put tails on 5' ends.`,
  },
  [r`The restriction point in $G_1$ commits a cell to:`]: {
    question: r`Cultured fibroblasts are growing in medium with growth factors. The growth factors are then washed away. What happens to the cells that had already passed the restriction point in G₁ at that moment?`,
    options: [r`They finish this division, then arrest in the next G₁`, r`They arrest at once, wherever they are in the cycle`, r`They return to G₁ without replicating their DNA`, r`They skip S phase and go directly into mitosis`],
    correctAnswer: 0,
    explanation: r`Passing the restriction point commits a cell to complete the cycle without further outside signals, so these cells replicate their DNA and divide, and only their daughters stop in G₁. Stopping immediately or going back to G₁ would mean the cell still depended on growth factors. Mitosis cannot occur without S phase.`,
  },
  [r`A transcription factor binds:`]: {
    question: r`Two bases are changed inside a 10 bp element that lies 3 kb upstream of a gene. A regulatory protein with a normal amino acid sequence no longer associates with this region, and the gene's transcription falls. What does this show about the protein?`,
    options: [r`It recognizes a specific mRNA codon set`, r`It binds any DNA with equal affinity`, r`It binds RNA polymerase but never DNA`, r`It recognizes a specific DNA base sequence`],
    correctAnswer: 3,
    explanation: r`A transcription factor binds a particular DNA sequence, so changing two bases of its site is enough to stop it binding and to change the gene's transcription. A protein that bound any DNA equally would not care about two bases. The experiment involves DNA, not codons in mRNA, and shows direct dependence on the DNA site.`,
  },
  [r`RNA interference silences genes by:`]: {
    question: r`Short double-stranded RNA matching the mRNA of gene X is introduced into cultured cells. The DNA of gene X is unchanged and its transcription rate is unchanged, yet protein X almost disappears. What happened?`,
    options: [r`X protein was cleaved after binding the small RNA`, r`X gene was deleted after pairing with the small RNA`, r`X mRNA was cleaved after pairing with the small RNA`, r`X promoter was blocked after binding the small RNA`],
    correctAnswer: 2,
    explanation: r`In RNA interference a small RNA loaded into RISC pairs with the complementary mRNA, which is then destroyed, so the protein is no longer made. The small RNA does not bind or cut proteins. The stem states the gene is intact and transcription is unchanged, which excludes deletion and promoter block.`,
  },
  [r`Introns are:`]: {
    question: r`The primary transcript of a human gene is 9,000 nucleotides long. Its mature mRNA, not counting the poly-A tail, is 2,400 nucleotides long. What accounts for the missing 6,600 nucleotides?`,
    options: [r`Coding exons removed by splicing`, r`Untranslated regions cut by ribosomes`, r`Promoter sequence removed by capping`, r`Noncoding introns removed by splicing`],
    correctAnswer: 3,
    explanation: r`Introns are transcribed but then removed by the spliceosome, and in most human genes they make up most of the primary transcript. Exons are the parts that are kept. Untranslated regions stay in the mature mRNA, and the promoter is not transcribed at all.`,
  },
  [r`The lac operon is an example of:`]: {
    question: r`E. coli mutant 1 lacks the lac repressor and expresses the lac operon even without lactose. Mutant 2 lacks CAP and expresses the operon only weakly even with lactose present and glucose absent. What do the two mutants show together?`,
    options: [r`The repressor acts positively and CAP acts negatively`, r`The repressor and CAP are both negative regulators`, r`The repressor acts negatively and CAP acts positively`, r`The repressor and CAP are both positive regulators`],
    correctAnswer: 2,
    explanation: r`Losing a negative regulator turns a gene on, as with the repressor, while losing a positive regulator turns it down, as with CAP. The lac operon therefore has both kinds of control. The other choices assign the wrong sign to one or both proteins.`,
  },
  [r`Alternative splicing allows one gene to:`]: {
    question: r`A gene has a first exon and a last exon that are always included, plus three internal exons that can each be included or skipped independently. What is the largest number of different mature mRNAs this gene can produce?`,
    options: [r`3`, r`6`, r`9`, r`8`],
    correctAnswer: 3,
    explanation: r`Each of the three optional exons has two states, included or skipped, so there are 2 × 2 × 2 = 8 combinations. Answering 3 counts the optional exons instead of their combinations, 6 multiplies 3 by 2, and 9 squares 3.`,
  },
  [r`In the nucleus, the pri-miRNA is cropped by {{c1::Drosha}} (with DGCR8) into the ~70 nt hairpin pre-miRNA.`]: {
    question: r`The gene for Drosha is knocked out in a cell line. Which RNA species is expected to build up in these cells?`,
    options: [r`Hairpin precursor miRNAs in the cytoplasm`, r`Mature miRNA duplexes in the nucleus`, r`Short guide strands bound to Argonaute`, r`Long primary miRNA transcripts in the nucleus`],
    correctAnswer: 3,
    explanation: r`Drosha makes the first cut, in the nucleus, turning the long pri-miRNA into the ~70 nt hairpin pre-miRNA, so without it the pri-miRNA accumulates. Hairpins piling up in the cytoplasm would point to loss of Dicer. Mature duplexes and loaded guide strands are later products that cannot form without the first cut.`,
  },
  [r`Introns begin with {{c1::GU}} at the 5' splice site and end with AG at the 3' splice site.`]: {
    question: r`A sequencing report describes a patient's mutation as a G to A change at the first nucleotide of intron 4. Which splicing signal has been destroyed?`,
    options: [r`The GU at the 5' splice site`, r`The AG at the 3' splice site`, r`The A at the branch point`, r`The AAUAAA poly-A signal`],
    correctAnswer: 0,
    explanation: r`Introns begin with GU, so the first nucleotide of an intron is the G of the 5' splice site. The AG is the last two nucleotides of the intron, the branch-point A lies inside the intron near its 3' end, and AAUAAA is a 3' end processing signal that is not part of an intron boundary.`,
  },
  [r`Why are splice-site mutations frequently pathogenic even though they don't change a codon?`]: {
    question: r`A mutation destroys the AG at the end of intron 4, and exon 5 is skipped so that exon 4 is joined directly to exon 6. Exon 5 is 90 nucleotides long and encodes part of the protein's binding domain. What is the effect on the protein?`,
    options: [r`It lacks 90 internal amino acids but keeps its frame`, r`It is frameshifted at every codon after exon 4`, r`It is unchanged, since no codon was mutated`, r`It lacks 30 internal amino acids but keeps its frame`],
    correctAnswer: 3,
    explanation: r`Skipping a 90-nucleotide exon removes 90 ÷ 3 = 30 codons, and because 90 is a multiple of 3 the downstream frame is kept, so the protein is missing part of a domain. Losing 90 amino acids confuses nucleotides with codons. A frameshift would need a length that is not a multiple of 3, and a protein missing 30 residues is not unchanged.`,
  },
  [r`What are group I and group II self-splicing introns, and why are group II introns evolutionarily interesting?`]: {
    question: r`An RNA purified from a mitochondrion is incubated in buffer with Mg²⁺ and no protein. It removes one of its own internal segments, and that segment is released as a lariat. What is the best conclusion?`,
    options: [r`It is a group I intron that needs a spliceosome`, r`It is a nuclear intron cut out by snRNPs`, r`It is a group II intron acting as a ribozyme`, r`It is a tRNA intron cut by a protein enzyme`],
    correctAnswer: 2,
    explanation: r`Splicing without any protein means the RNA is catalytic, and release as a lariat is the mark of a group II self-splicing intron, the same chemistry the spliceosome uses. Group I introns also self-splice, but they need no spliceosome and do not form a lariat. snRNPs and protein enzymes were absent from the buffer.`,
  },
  [r`How does target-pairing extent decide the fate of an mRNA bound by RISC?`]: {
    question: r`Small RNA 1 pairs perfectly along its whole length with an mRNA. Small RNA 2 pairs with a different mRNA only through nucleotides 2 to 8 and a few scattered bases. Both are loaded into RISC. What happens to the two mRNAs?`,
    options: [r`The first is repressed and deadenylated; the second is sliced`, r`Both are sliced by Argonaute in the middle of the paired site`, r`The first is sliced; the second is repressed and deadenylated`, r`Both are repressed and deadenylated, and neither is sliced`],
    correctAnswer: 2,
    explanation: r`Perfect complementarity lets Argonaute cut the target, which is the siRNA outcome, while partial pairing blocks translation and promotes loss of the poly-A tail, which is the usual animal miRNA outcome. The reversed choice swaps the two rules. The remaining two ignore that the extent of pairing decides the fate.`,
  },
  [r`Where on an mRNA do animal miRNAs usually bind, and which part of the miRNA does the recognizing?`]: {
    question: r`A lab wants to predict by computer which mRNAs are regulated by a newly found animal miRNA. Which search is most appropriate?`,
    options: [r`Scan 5' UTRs for matches to miRNA bases 2 to 8`, r`Scan 3' UTRs for matches to miRNA bases 2 to 8`, r`Scan 3' UTRs for matches to miRNA bases 14 to 21`, r`Scan promoters for matches to miRNA bases 14 to 21`],
    correctAnswer: 1,
    explanation: r`Animal miRNAs usually bind the 3' UTR of their targets, and recognition depends mainly on the seed, nucleotides 2 to 8 at the miRNA's 5' end. Searching 5' UTRs looks in the wrong region, bases 14 to 21 are outside the seed, and miRNAs pair with mRNA, not with promoter DNA.`,
  },
  [r`Intrinsic bacterial termination requires a {{c1::GC-rich hairpin followed by a run of U residues}}; Rho-dependent termination uses an ATP-driven helicase.`]: {
    question: r`In a bacterial intrinsic terminator, the bases that encode the run of U residues are changed so the transcript now has a mix of G and C there. The GC-rich hairpin still forms. What is expected at this site?`,
    options: [r`Polymerase terminates normally at the very same site`, r`Polymerase never pauses, since no hairpin can form`, r`Polymerase terminates earlier, before the hairpin`, r`Polymerase pauses at the hairpin but then reads through`],
    correctAnswer: 3,
    explanation: r`The hairpin stalls the polymerase, but release depends on the weak rU-dA hybrid that lets the transcript peel away. With strong G-C pairs in its place the transcript stays attached and the polymerase continues. Normal termination ignores the need for the U run, and the stem says the hairpin still forms.`,
  },
  [r`How do cells make tissue-specific splicing decisions from the same pre-mRNA?`]: {
    question: r`In neurons a protein binds an enhancer element inside exon 6 of a pre-mRNA, and exon 6 is included in the mRNA. In liver the protein is absent and exon 6 is skipped. This protein behaves most like:`,
    options: [r`an SR protein that promotes splice-site use`, r`an hnRNP protein that blocks splice-site use`, r`a sigma factor that directs promoter choice`, r`a Dicer enzyme that cleaves the exon's RNA`],
    correctAnswer: 0,
    explanation: r`SR proteins bind splicing enhancers and help the spliceosome use nearby splice sites, so an exon is included where the SR protein is present. An hnRNP that blocks splice sites would cause skipping where it is present, the opposite of what is seen. Sigma factors act on bacterial promoters, and Dicer processes small RNAs.`,
  },
  [r`How does the pre-miRNA hairpin reach the cytoplasm?`]: {
    question: r`A drug selectively blocks Exportin-5. Which RNA never reaches its next processing enzyme?`,
    options: [r`The ~70 nt pre-miRNA hairpin, which needs Dicer`, r`The long pri-miRNA transcript, which needs Drosha`, r`The ~22 nt miRNA duplex, which needs Drosha`, r`The spliced mature mRNA, which needs Dicer`],
    correctAnswer: 0,
    explanation: r`Exportin-5 carries the pre-miRNA hairpin out of the nucleus to cytoplasmic Dicer, so blocking it traps the hairpin in the nucleus. The pri-miRNA meets Drosha inside the nucleus without any export. The ~22 nt duplex is made after Dicer, and mRNA is not a Dicer substrate and leaves by a different export route.`,
  },
  [r`After Dicer, the guide strand loads into RISC, whose catalytic slicer protein is {{c1::Argonaute}}.`]: {
    question: r`A cell line makes an Argonaute that still binds guide RNA but has lost its catalytic activity. An siRNA with perfect complementarity to an mRNA is introduced. What is expected?`,
    options: [r`RISC cannot find the target, as no guide loads`, r`RISC pairs with the target but cannot slice it`, r`Dicer slices the target mRNA in place of RISC`, r`Drosha slices the target mRNA in the cytoplasm`],
    correctAnswer: 1,
    explanation: r`Argonaute holds the guide strand and is also the slicer that cuts a perfectly paired target, so a catalytically dead version still finds the mRNA but leaves it uncut. The stem says the guide still loads. Dicer and Drosha cut miRNA precursors, not target mRNAs, and Drosha is nuclear.`,
  },
  [r`How does transcription of a eukaryotic Pol II gene actually end?`]: {
    question: r`Cells are depleted of the nuclear 5'-to-3' exonuclease that acts after pre-mRNA cleavage. Cleavage at the poly(A) site still occurs normally. What is expected at Pol II genes?`,
    options: [r`Pol II stops early, before reaching the AAUAAA signal`, r`Pol II releases mRNA that was never cleaved at its 3' end`, r`Pol II keeps transcribing far past the end of the gene`, r`Pol II is unaffected, since cleavage alone releases it`],
    correctAnswer: 2,
    explanation: r`After the transcript is cut at the poly-A site, a torpedo exonuclease chews the RNA still attached to Pol II from its new 5' end and knocks the polymerase off the DNA. Without it Pol II keeps going downstream. Cleavage was stated to be normal, and cleavage by itself does not dislodge the polymerase.`,
  },
  [r`How do bacteria redirect transcription globally during stress such as heat shock?`]: {
    question: r`An E. coli strain has a deletion of the gene for sigma-32 but makes normal sigma-70 and normal core RNA polymerase. The culture is shifted to a high temperature. What is the direct consequence?`,
    options: [r`Core polymerase unfolds and all transcription stops`, r`Sigma-70 redirects polymerase to heat-shock promoters`, r`Heat-shock mRNAs are made but cannot be translated`, r`Heat-shock promoters are not recognized by polymerase`],
    correctAnswer: 3,
    explanation: r`Each sigma factor directs the same core enzyme to its own set of promoters, and sigma-32 is the one that reads heat-shock promoters, so without it those genes are not induced. Sigma-70 recognizes housekeeping promoters and cannot stand in. Nothing in the stem damages the core enzyme or translation.`,
  },
  [r`Which eukaryotic mRNAs famously lack a poly(A) tail, and what replaces it?`]: {
    question: r`A drug blocks polyadenylation of all newly made transcripts in dividing human cells. Which class of mRNA still receives its normal 3' end?`,
    options: [r`Beta-globin mRNAs of red cell precursors`, r`Cytokine mRNAs of activated immune cells`, r`Replication-dependent histone mRNAs`, r`Ribosomal protein mRNAs of growing cells`],
    correctAnswer: 2,
    explanation: r`Replication-dependent histone mRNAs have no poly-A tail. They end in a conserved stem-loop bound by SLBP, so a block in polyadenylation does not affect them. Globin, cytokine and ribosomal protein mRNAs are all polyadenylated.`,
  },
  [r`Distinguish general transcription factors from specific (regulatory) transcription factors.`]: {
    question: r`Protein A is found at the core promoter of every Pol II gene tested, in every cell type. Protein B is found at an enhancer of the albumin gene, and only in liver cells. How are A and B best classified?`,
    options: [r`A is a specific factor; B is a general factor`, r`A is a general factor; B is a specific factor`, r`A and B are both general transcription factors`, r`A and B are both specific transcription factors`],
    correctAnswer: 1,
    explanation: r`General transcription factors assemble at every Pol II core promoter and are needed for basal initiation, while specific factors bind the enhancers or silencers of particular genes in particular cell types. Protein A fits the first description and protein B the second. The other choices swap or merge the two categories.`,
  },
  [r`Name four common DNA-binding motifs found in transcription factors.`]: {
    question: r`A nuclear protein has a leucine at every seventh position along one alpha helix, with a stretch of basic residues next to it. It binds DNA only as a pair with a second, similar protein. Which motif does it contain?`,
    options: [r`A zinc finger that holds a metal ion`, r`A leucine zipper that pairs two helices`, r`A helix-turn-helix of a homeodomain`, r`A beta barrel that spans a membrane`],
    correctAnswer: 1,
    explanation: r`Leucines repeated every seven residues line up on one face of a helix and zip two such helices together, as in Fos and Jun, while the basic region contacts the DNA. A zinc finger is defined by cysteine and histidine residues holding zinc, a helix-turn-helix does not depend on a leucine repeat, and a beta barrel is a membrane pore fold.`,
  },
  [r`What two functional domains does a typical activator protein contain?`]: {
    question: r`A chimeric protein joins the DNA-binding domain of bacterial LexA to the activation domain of yeast Gal4. It is expressed in yeast carrying two reporter genes: one preceded by LexA binding sites and one preceded by Gal4 binding sites. No normal Gal4 is present. Which reporter is activated?`,
    options: [r`Only the reporter with Gal4 binding sites`, r`Both reporters, to the same high level`, r`Neither reporter, as the domains clash`, r`Only the reporter with LexA binding sites`],
    correctAnswer: 3,
    explanation: r`An activator's DNA-binding domain decides where it goes and its activation domain decides what it does there, and the two are separable. The chimera is carried to LexA sites, where the Gal4 activation domain recruits the transcription machinery. It cannot find Gal4 sites because it lacks the Gal4 DNA-binding domain, and domain swaps like this do work.`,
  },
  [r`U1 snRNP base-pairs with the 5' splice site, while {{c1::U2}} base-pairs with the branch-point sequence.`]: {
    question: r`An antisense oligonucleotide covers the region of U2 snRNA that base-pairs with pre-mRNA. Which event is directly prevented?`,
    options: [r`Recognition of the GU at the 5' splice site`, r`Cleavage at the AAUAAA poly(A) signal`, r`Bulging out of the branch-point adenosine`, r`Addition of the 7-methylguanosine cap`],
    correctAnswer: 2,
    explanation: r`U2 pairs with the branch-point sequence and pushes the branch adenosine out of the helix so its 2'-OH can attack. Recognition of the 5' splice site is the job of U1. Cleavage at the poly-A signal and capping are done by other factors and do not use U2.`,
  },
  [r`The lariat forms when the branch-point adenosine's {{c1::2'-OH}} attacks the 5' splice site, creating a rare 2'-5' phosphodiester bond.`]: {
    question: r`A synthetic pre-mRNA is made in which the branch-point adenosine is a 2'-deoxyadenosine. All other nucleotides are normal. What happens when it is added to a splicing extract?`,
    options: [r`A lariat forms using the 3'-OH of that same adenosine`, r`A lariat forms, but the exons cannot then be ligated`, r`No lariat forms, as step one has lost its nucleophile`, r`Exons ligate normally while the intron stays linear`],
    correctAnswer: 2,
    explanation: r`The first step of splicing is an attack by the branch adenosine's 2'-OH on the 5' splice site, forming the 2'-5' bond of the lariat. Without that hydroxyl there is no first step, and the second step cannot follow. The adenosine's 3'-OH is already used in the RNA backbone, and exons cannot be joined before the 5' splice site is cut.`,
  },
  [r`Describe the two transesterification steps of splicing in order.`]: {
    question: r`A splicing reaction on a two-exon pre-mRNA is stopped after the first transesterification and before the second. Which RNA species are present?`,
    options: [r`Free exon 1, and a lariat intron still joined to exon 2`, r`Free exon 2, and a lariat intron still joined to exon 1`, r`Ligated exons 1 and 2, and a free lariat intron`, r`Intact linear pre-mRNA, and a free branch adenosine`],
    correctAnswer: 0,
    explanation: r`Step one cuts the 5' splice site: exon 1 is freed with a new 3'-OH and the intron loops into a lariat that is still attached to exon 2. Only step two joins the exons and releases the lariat. The branch adenosine is never released on its own, and it is exon 1, not exon 2, that is freed first.`,
  },
  [r`What are snRNPs made of, and what does the catalysis of splicing?`]: {
    question: r`A single-base change in U6 snRNA abolishes both chemical steps of splicing. All spliceosomal proteins are normal, and the spliceosome still assembles on the pre-mRNA. What does this result best support?`,
    options: [r`snRNA is only a scaffold that holds protein enzymes`, r`snRNA forms the catalytic center of the spliceosome`, r`snRNA is translated into the catalytic polypeptide`, r`snRNA supplies the energy for each bond exchange`],
    correctAnswer: 1,
    explanation: r`Losing catalysis from one RNA base change, with assembly and all proteins intact, points to the RNA itself doing the chemistry: the U2/U6 snRNAs form the active site, so the spliceosome is in effect a ribozyme. A pure scaffold defect would disturb assembly. snRNAs are not translated and are not an energy source.`,
  },
  [r`Alternative splicing lets roughly 20,000 human genes encode a far larger proteome; the most common pattern is {{c1::exon skipping}}.`]: {
    question: r`Two mRNAs come from one gene. Isoform A contains exons 1, 2, 3 and 4. Isoform B contains exons 1, 2 and 4, and every exon it does contain has the same boundaries as in isoform A. Which pattern of alternative splicing is this?`,
    options: [r`Intron retention`, r`Mutually exclusive exons`, r`Alternative 5' site use`, r`Cassette exon skipping`],
    correctAnswer: 3,
    explanation: r`A whole internal exon is present in one isoform and left out of the other, which is exon skipping, the most common pattern in humans. Intron retention would add intron sequence, mutually exclusive exons would swap one exon for another, and an alternative 5' site would change an exon's boundary.`,
  },
  [r`The eukaryotic TATA box sits about {{c1::25}} bp upstream of the start site and is bound by TBP within TFIID.`]: {
    question: r`In a TATA-dependent promoter, 15 bp of random sequence are inserted between the TATA box and the normal transcription start site. Where does transcription now begin?`,
    options: [r`About 40 bp downstream of TATA, at the old position`, r`About 10 bp upstream of TATA, at a new position`, r`About 25 bp downstream of TATA, at a new position`, r`Within the TATA box itself, at the first T`],
    correctAnswer: 2,
    explanation: r`The TATA box sits about 25 bp upstream of the start site and sets where Pol II begins, so the start stays about 25 bp from TATA and therefore falls on new sequence. Keeping the old position would assume the start site defines itself. Pol II does not start upstream of or inside the TATA box.`,
  },
  [r`{{c1::Enhancers}} stimulate transcription regardless of their orientation or distance from the promoter.`]: {
    question: r`In a B-cell tumor, a chromosomal translocation places the strong enhancer of an antibody gene about 100 kb away from a growth-promoting gene, in the opposite orientation to that gene. The growth gene's own promoter is intact. What is expected in these B cells?`,
    options: [r`Transcription of the growth gene falls`, r`The growth gene is cut out of the DNA`, r`Nothing, since the enhancer is inverted`, r`Transcription of the growth gene rises`],
    correctAnswer: 3,
    explanation: r`Enhancers stimulate transcription regardless of orientation and across long distances, because the DNA between them and the promoter loops out. An antibody-gene enhancer is very active in B cells, so the nearby growth gene is driven hard. An enhancer does not lower transcription or remove DNA, and inversion does not disable it.`,
  },
  [r`Bacterial promoters carry consensus elements at {{c1::-10 (TATAAT, the Pribnow box) and -35}}, read by the sigma factor.`]: {
    question: r`The -10 element of a bacterial promoter is mutated from TATAAT to TGCGCT. The -35 element is unchanged. What is the expected effect?`,
    options: [r`Weaker sigma binding and harder DNA melting`, r`Stronger sigma binding and easier DNA melting`, r`No effect, as sigma reads only the -35 element`, r`No effect, as ribosomes read the -10 element`],
    correctAnswer: 0,
    explanation: r`Sigma reads both the -35 and the -10 consensus sequences, and the AT-rich -10 element is also where the DNA opens, so replacing it with GC-rich sequence weakens recognition and makes melting harder. A poorer match to consensus never strengthens a promoter. The -10 element is a transcription signal, not a ribosome binding site.`,
  },
  [r`What does the bacterial sigma factor do, and what happens to it after initiation?`]: {
    question: r`In a test tube, bacterial RNA polymerase holoenzyme is allowed to start transcription, and every polymerase has made a 50-nucleotide RNA. An antibody that inactivates sigma factor is then added. What happens to these transcripts?`,
    options: [r`They stop growing, since sigma forms each bond`, r`They are released, since sigma holds the RNA`, r`They keep growing, since sigma has already left`, r`They keep growing only if new sigma is added`],
    correctAnswer: 2,
    explanation: r`Sigma is needed only to find the promoter. Once elongation is under way it is released and the core enzyme continues alone, so inactivating sigma does not affect polymerases that are already elongating. Sigma does not catalyze bond formation and does not hold the transcript. Only new rounds of initiation would be blocked.`,
  },
  [r`What is structurally unusual about how TBP binds the TATA box?`]: {
    question: r`A small molecule fills the minor groove at TATA sequences and leaves the major groove open. It blocks initiation at TATA-containing Pol II promoters. Which explanation fits?`,
    options: [r`TBP contacts the major groove and bends the DNA`, r`Sigma contacts the minor groove at the -10 box`, r`Pol II contacts the TATA box without any TBP`, r`TBP contacts the minor groove and bends the DNA`],
    correctAnswer: 3,
    explanation: r`TBP is unusual in binding its site through the minor groove, and it bends the DNA sharply to create the platform for the rest of the preinitiation complex, so a minor-groove blocker keeps it off. If TBP used the major groove the drug would not interfere. Sigma is bacterial, and Pol II does not read the TATA box by itself.`,
  },
  [r`What role does the Mediator complex play at Pol II genes?`]: {
    question: r`Cells are depleted of the Mediator complex. Activators still bind their enhancers, and the general transcription factors and Pol II are present. What is the main defect?`,
    options: [r`Activators bind but cannot signal to Pol II`, r`Activators can no longer bind enhancer DNA`, r`TBP can no longer recognize the TATA box`, r`Introns can no longer be removed from RNA`],
    correctAnswer: 0,
    explanation: r`Mediator is the bridge between activators bound at enhancers and the Pol II preinitiation complex, so without it the activators sit on the DNA but their signal does not reach the polymerase. The stem says activators still bind. TATA recognition belongs to TBP, and splicing belongs to the spliceosome.`,
  },
  [r`What are silencer elements, and how do they act?`]: {
    question: r`Deleting a 200 bp element that lies 8 kb upstream of gene N raises transcription of N fivefold in non-neuronal cells. In those cells the element is normally bound by a protein that recruits a histone deacetylase. What is the element?`,
    options: [r`An enhancer bound by an activator`, r`A silencer bound by a repressor`, r`A promoter bound by general factors`, r`An origin bound by a helicase`],
    correctAnswer: 1,
    explanation: r`Removing the element increases transcription, so it normally lowers it, and it does so from a distance through a bound protein that recruits a deacetylase: that is a silencer with its repressor. Deleting an enhancer or a promoter would lower transcription. An origin of replication does not set a gene's transcription level.`,
  },
  [r`What does RNA Pol I transcribe, and where?`]: {
    question: r`A compound selectively inhibits RNA Pol I in human cells. Which ribosomal RNA continues to be made?`,
    options: [r`18S rRNA, made by Pol II outside the nucleolus`, r`5S rRNA, made by Pol III outside the nucleolus`, r`28S rRNA, made by Pol III inside the nucleolus`, r`5.8S rRNA, made by Pol II inside the nucleolus`],
    correctAnswer: 1,
    explanation: r`Pol I makes the 45S precursor in the nucleolus, and that precursor is cut into the 18S, 5.8S and 28S rRNAs, so all three stop. The 5S rRNA is the exception: it is transcribed by Pol III outside the nucleolus. The other choices assign 45S-derived rRNAs to the wrong polymerase.`,
  },
  [r`RNA Pol {{c1::III}} synthesizes tRNAs, 5S rRNA, and other small RNAs — and some of its promoters lie inside the gene.`]: {
    question: r`Deleting all of the DNA upstream of a tRNA gene's start site does not stop its transcription, but deleting a short segment inside the transcribed region does. What explains this?`,
    options: [r`Pol II uses promoter elements inside the gene`, r`Pol III uses promoter elements inside the gene`, r`Pol I uses enhancers placed far downstream`, r`Pol III starts without any promoter at all`],
    correctAnswer: 1,
    explanation: r`tRNA genes are transcribed by Pol III, and their promoters (the A and B boxes) lie within the transcribed sequence, so an internal deletion removes the promoter while an upstream deletion does not. Pol II and Pol I do not transcribe tRNA genes. If no promoter were needed, the internal deletion would not matter.`,
  },
  [r`Insulator elements bound by {{c1::CTCF}} prevent an enhancer from activating the wrong promoter.`]: {
    question: r`Enhancer E normally activates gene A. A CTCF-binding site lies between E and a neighboring gene B, which E does not activate. The CTCF site is deleted. What is the most likely result?`,
    options: [r`E no longer activates gene A on its own side`, r`E now also activates gene B across the lost boundary`, r`E becomes a silencer that shuts off both genes`, r`E is unaffected, since CTCF binds only promoters`],
    correctAnswer: 1,
    explanation: r`CTCF-bound insulators divide the genome into loop domains and stop an enhancer from contacting promoters across the boundary. Removing the insulator lets E reach gene B as well. Nothing here stops E from contacting gene A or converts it to a silencer, and CTCF's role is at insulators.`,
  },
  [r`Beyond mRNA, which RNAs does Pol II produce?`]: {
    question: r`A cell line carries a Pol II that is rapidly destroyed when a drug is added, while Pol I and Pol III are untouched. Besides mRNA, synthesis of which RNAs stops directly?`,
    options: [r`Transfer RNAs and the 5S ribosomal RNA`, r`The 45S precursor of the large rRNAs`, r`The 18S, 5.8S and 28S ribosomal RNAs`, r`Pri-miRNAs and most spliceosomal snRNAs`],
    correctAnswer: 3,
    explanation: r`Pol II also transcribes the primary miRNA transcripts and most snRNAs, which is why pri-miRNAs are capped and polyadenylated like mRNAs. tRNAs and 5S rRNA come from Pol III. The 45S precursor and the 18S, 5.8S and 28S rRNAs cut from it come from Pol I.`,
  },
  [r`Alpha-amanitin most potently inhibits RNA Pol {{c1::II}}; Pol III is moderately sensitive and Pol I essentially resistant.`]: {
    question: r`In isolated nuclei, synthesis of RNA X is blocked by a very low dose of alpha-amanitin. Synthesis of RNA Y is blocked only at a high dose. Synthesis of RNA Z continues at every dose tested. Which polymerases make X, Y and Z?`,
    options: [r`X by Pol II, Y by Pol III, Z by Pol I`, r`X by Pol III, Y by Pol II, Z by Pol I`, r`X by Pol I, Y by Pol III, Z by Pol II`, r`X by Pol II, Y by Pol I, Z by Pol III`],
    correctAnswer: 0,
    explanation: r`Alpha-amanitin sensitivity runs Pol II, then Pol III, then Pol I: Pol II is blocked at very low doses, Pol III only at high doses, and Pol I is essentially resistant. The other choices put the polymerases in the wrong order of sensitivity.`,
  },
  [r`TFIIH supplies two enzyme activities at initiation: {{c1::helicase (promoter melting) and CTD kinase}}.`]: {
    question: r`A mutant TFIIH has lost its kinase activity but keeps its helicase activity. What is expected at a Pol II promoter?`,
    options: [r`The promoter DNA opens, but the Pol II CTD stays unphosphorylated`, r`The promoter DNA stays closed, but the Pol II CTD is phosphorylated`, r`The promoter DNA opens, but TBP can no longer bind the TATA box`, r`The promoter DNA stays closed, and the Pol II CTD stays unmodified`],
    correctAnswer: 0,
    explanation: r`TFIIH's helicase melts the promoter to form the open complex, and its kinase phosphorylates the Pol II CTD to launch elongation. With only the kinase lost, the DNA opens but the CTD is not phosphorylated. A closed promoter would mean the helicase was lost, and TBP binding does not depend on TFIIH's kinase.`,
  },
  [r`Why does phosphorylation of the Pol II CTD matter for mRNA processing?`]: {
    question: r`Cells express a Pol II whose C-terminal domain cannot be phosphorylated but whose catalytic site is normal. In a system where this polymerase still transcribes a gene, what is expected of the transcripts?`,
    options: [r`They are made and processed normally, but then never exported`, r`They are made, but poorly capped, spliced and polyadenylated`, r`They are not made, since the CTD forms the catalytic site`, r`They are processed normally, as factors find the RNA unaided`],
    correctAnswer: 1,
    explanation: r`The phosphorylated CTD is the landing pad that carries capping, splicing and cleavage/polyadenylation factors along with the polymerase, so without it processing is badly impaired even though RNA is made. The CTD is not the catalytic site. Processing factors depend on the CTD to reach the growing transcript efficiently.`,
  },
  [r`What does the U4/U6-U5 tri-snRNP contribute to spliceosome assembly?`]: {
    question: r`A splicing extract is depleted of the U4/U6-U5 tri-snRNP. All other components are present. At what stage does spliceosome assembly stop?`,
    options: [r`U1 and U2 are bound, but no catalytic center forms`, r`U6 and U5 are bound, but U1 cannot find the 5' site`, r`Both steps occur, but the lariat cannot be released`, r`No snRNP binds, as U1 needs U6 to find the intron`],
    correctAnswer: 0,
    explanation: r`U1 and U2 mark the 5' splice site and branch point first. The tri-snRNP then joins, and U6 replaces U1 and pairs with U2 to make the active site, so without it the complex stalls before any chemistry. U6 and U5 are part of the missing particle, and U1 binds the 5' site without help from U6.`,
  },
  [r`A poly(A) tail begins near {{c1::200}} adenines, and progressive {{c2::deadenylation}} is usually the first and rate-limiting step of mRNA decay.`]: {
    question: r`A newly exported mRNA is followed in the cytoplasm until it is destroyed. Which change is expected to be detected first?`,
    options: [r`Shortening of a poly(A) tail of about 200 adenines`, r`Removal of the 5' cap by a decapping enzyme`, r`Digestion of the mRNA body from its 5' end`, r`Shortening of a poly(A) tail of about 20 adenines`],
    correctAnswer: 0,
    explanation: r`A new tail is about 200 adenines long, and its gradual shortening is usually the first and slowest step of mRNA decay. Decapping and 5'-to-3' digestion follow only once the tail is short. A tail does not start at about 20 adenines.`,
  },
  [r`Why does a nonsense mutation in exon 3 of a 20-exon gene often yield no truncated protein at all?`]: {
    question: r`A 10-exon gene has two mutant alleles. Allele A has a nonsense mutation in exon 2. Allele B has a nonsense mutation in exon 10, the last exon, 30 codons before the normal stop. Which allele is more likely to produce a detectable truncated protein?`,
    options: [r`A, since its stop codon lies closest to the 5' cap`, r`Both, since a stop codon never changes mRNA levels`, r`Neither, since both mRNAs are destroyed by decay`, r`B, since no exon junction lies downstream of its stop`],
    correctAnswer: 3,
    explanation: r`Nonsense-mediated decay destroys an mRNA when a ribosome stops upstream of an exon junction complex that it has not yet removed. The stop in exon 2 leaves many junctions downstream, so that mRNA is degraded, while a stop in the last exon has none after it and escapes. Stop codons can lower mRNA levels, but not in every position.`,
  },
  [r`RNA polymerase errs about once per {{c1::$10^{4}$}} nucleotides, far more often than replication, because transcripts are {{c2::disposable}}.`]: {
    question: r`RNA polymerase transcribes a 10,000-nucleotide gene. About how many errors does a typical transcript carry, and why does the cell tolerate this?`,
    options: [r`About 1 error; it is repaired later by DNA polymerase`, r`About 1 error; the faulty mRNA is soon degraded and remade`, r`About 0.00001 errors; RNA polymerase proofreads like DNA Pol`, r`About 100 errors; most of each mRNA is never translated`],
    correctAnswer: 1,
    explanation: r`RNA polymerase makes roughly one error per 10⁴ nucleotides, so a 10,000-nucleotide transcript carries about one. This is acceptable because an mRNA is temporary and is not inherited, unlike a replication error. A rate near 10⁻⁹ belongs to DNA replication, 100 errors would be a rate of 1 in 100, and DNA polymerase does not repair RNA.`,
  },
  [r`Ribosomal RNA is about {{c1::80}} percent of cellular RNA while mRNA is only a few percent, which is why {{c2::Pol I}} accounts for most transcription.`]: {
    question: r`A lab sequences total RNA from growing human cells without first removing any RNA class. What should it expect of the reads?`,
    options: [r`About 80% are mRNA, made mostly by Pol II`, r`About 80% are rRNA, made mostly by Pol I`, r`About 80% are tRNA, made mostly by Pol III`, r`About 5% are rRNA, made mostly by Pol I`],
    correctAnswer: 1,
    explanation: r`Ribosomal RNA is about 80 percent of the RNA in a cell, and most of it comes from the Pol I transcript, while mRNA is only a few percent. That is why rRNA is usually removed before mRNA sequencing. The other choices give the top share to mRNA or tRNA, or give rRNA the share that belongs to mRNA.`,
  },
  [r`{{c1::Rifampin}} inhibits the beta subunit of bacterial RNA polymerase, while alpha-amanitin inhibits eukaryotic RNA Pol {{c2::II}}.`]: {
    question: r`Human cells infected with an intracellular bacterium are split into two dishes. Dish 1 receives rifampin. Dish 2 receives a low dose of alpha-amanitin. What is the direct effect in each dish?`,
    options: [r`Dish 1: host mRNA synthesis stops. Dish 2: bacterial RNA synthesis stops`, r`Dish 1 and dish 2: bacterial RNA synthesis stops, host is unaffected`, r`Dish 1: bacterial RNA synthesis stops. Dish 2: host mRNA synthesis stops`, r`Dish 1 and dish 2: host mRNA synthesis stops, bacteria are unaffected`],
    correctAnswer: 2,
    explanation: r`Rifampin binds the beta subunit of bacterial RNA polymerase and spares the eukaryotic enzymes, while alpha-amanitin at low dose blocks eukaryotic Pol II and so stops host mRNA synthesis. The reversed choice swaps the two targets. The drugs do not share a target, so neither dish shows the same effect as the other.`,
  },
  [r`Pol II elongates at roughly 40-80 nucleotides per second. What does that mean for the 2.2 Mb dystrophin gene?`]: {
    question: r`Pol II moves along a gene at about 50 nucleotides per second. About how long does it take one polymerase to transcribe a gene that is 1,800,000 nucleotides long?`,
    options: [r`About 10 minutes`, r`About 1 hour`, r`About 100 hours`, r`About 10 hours`],
    correctAnswer: 3,
    explanation: r`1,800,000 ÷ 50 = 36,000 seconds, and 36,000 ÷ 3,600 = 10 hours. Ten minutes comes from treating 36,000 seconds as 600 seconds, and the other values are off by a factor of ten. Very long genes therefore take many hours to transcribe once.`,
  },
  [r`Many stress and immune genes hold Pol II paused just downstream of the promoter. What advantage does promoter-proximal pausing provide?`]: {
    question: r`Genes A and B are induced by the same signal. Before the signal, gene A has a Pol II stalled about 40 nucleotides downstream of its start site, while gene B has no polymerase at its promoter. Which gene yields full-length transcripts first, and why?`,
    options: [r`A, since it only needs release of paused Pol II by P-TEFb`, r`B, since its promoter is not blocked by a stalled Pol II`, r`A, since a paused Pol II no longer needs its DNA template`, r`B, since new initiation is faster than pause release`],
    correctAnswer: 0,
    explanation: r`At gene A the slow steps of assembling the preinitiation complex and starting are already done, so a release signal from the kinase P-TEFb is enough to produce transcripts within seconds. Gene B must still recruit and start a polymerase. A paused polymerase still copies the template, and initiation is the slower step.`,
  },
  [r`Some beta-thalassemia alleles have a normal coding sequence but create a new splice site inside an intron. Why is that pathogenic?`]: {
    question: r`A mutation deep inside intron 2 of the beta-globin gene creates a new 3' splice site. The mature mRNA now carries 73 extra nucleotides of intron sequence between exons 2 and 3. No exon base is changed. What is the consequence?`,
    options: [r`The globin gains 73 extra amino acids but otherwise works normally`, r`The globin is normal, because every exon still has its own sequence`, r`The gene's transcription stops at the new site inside intron 2`, r`The reading frame shifts after exon 2, so little normal globin is made`],
    correctAnswer: 3,
    explanation: r`The spliceosome uses the new site, so intron sequence stays in the mRNA. Because 73 is not a multiple of 3, every codon after the insertion is read in the wrong frame and a stop codon soon appears. 73 nucleotides cannot encode 73 amino acids, unchanged exons do not guarantee a normal mRNA, and splice sites do not end transcription.`,
  },
  [r`A 5' deletion series loses promoter activity only when the region from -110 to -100 is removed. What has that identified?`]: {
    question: r`A promoter is tested by 5' deletions. Constructs that begin at -200 and at -150 have full activity, and a construct that begins at -120 has none. A student concludes that the -150 to -120 segment by itself can drive transcription. How should this be judged?`,
    options: [r`The segment is shown sufficient, but necessity is untested`, r`The segment is shown both necessary and sufficient`, r`The segment is shown necessary, but sufficiency is untested`, r`The segment is shown neither necessary nor sufficient`],
    correctAnswer: 2,
    explanation: r`Activity is lost only when the segment is removed, so it is required. Whether it can work alone needs a different experiment: placing the segment in front of a minimal promoter. Deletion mapping shows what is necessary and can never show sufficiency.`,
  },
  [r`In DNase I footprinting, a bound protein {{c1::protects}} its site from cleavage, leaving a blank gap in the ladder of fragments.`]: {
    question: r`A 200 bp DNA fragment labeled at one end is cut lightly with DNase I and run on a gel. Without added protein, bands appear at every length from 1 to 200. With protein P added before cutting, the bands from 80 to 95 are missing and all others remain. What is the conclusion?`,
    options: [r`Protein P cuts the DNA between bases 80 and 95`, r`Protein P binds everywhere except bases 80 to 95`, r`DNase I has no cut sites between bases 80 and 95`, r`Protein P covers bases 80 to 95 of the fragment`],
    correctAnswer: 3,
    explanation: r`A bound protein shields its site from DNase I, so fragments ending inside the site are missing and leave a gap, the footprint. If P cut the DNA there, extra bands would appear, not fewer. Binding everywhere else would remove the other bands, and the lane without protein shows that DNase I can cut within 80 to 95.`,
  },
  [r`The 5' cap is 7-methylguanosine joined by an unusual {{c1::5'-to-5' triphosphate}} bridge, leaving no free 5' end for exonucleases.`]: {
    question: r`A chemist probes a capped mRNA that has no poly(A) tail for nucleotides that carry a free 3'-OH group. How many such nucleotides are found, and why?`,
    options: [r`One: only the final nucleotide at the 3' end`, r`None: the cap's bridge uses up every 3'-OH`, r`Two: the cap guanosine and the final nucleotide`, r`Two: the first and second transcribed bases`],
    correctAnswer: 2,
    explanation: r`The cap is joined 5'-to-5' through a triphosphate bridge, so the cap guanosine's 3'-OH is left free, and the last nucleotide of the chain has the other free 3'-OH. No free 5' end exists, which is what protects the transcript from 5' exonucleases. Counting one ignores the cap's inverted linkage, and internal nucleotides use their 3'-OH in the backbone.`,
  },
  [r`A nuclear run-on shows unchanged transcription of a gene whose mRNA level has tripled. What explains the increase?`]: {
    question: r`After a hormone is added, a nuclear run-on assay shows that transcription of gene H has risen fivefold. The steady-state level of H mRNA has not changed. What explains this?`,
    options: [r`H mRNA is now degraded about five times slower`, r`H mRNA is now translated about five times faster`, r`H mRNA is now degraded about five times faster`, r`H protein is now degraded about five times faster`],
    correctAnswer: 2,
    explanation: r`Run-on measures the rate of synthesis, and the steady-state level reflects synthesis balanced against decay. If synthesis rises fivefold and the level stays the same, decay must also have risen about fivefold. Slower decay would raise the level even more, and translation or protein turnover does not set the amount of mRNA.`,
  },
  [r`How would you measure an mRNA's half-life using actinomycin D?`]: {
    question: r`Actinomycin D is added to cells to stop transcription. A transcript measures 800 units at the moment of addition and 100 units 6 hours later. What is its half-life?`,
    options: [r`3 hours`, r`2 hours`, r`6 hours`, r`45 minutes`],
    correctAnswer: 1,
    explanation: r`With no new synthesis the transcript only decays: 800 to 400 to 200 to 100 is three halvings in 6 hours, so each half-life is 2 hours. Three hours counts the number of halvings as the answer, 6 hours is the whole interval, and 45 minutes divides 6 hours by 8.`,
  },
  [r`How does one APOB gene yield full-length ApoB-100 in liver but truncated ApoB-48 in intestine?`]: {
    question: r`At one codon of a gene, intestinal genomic DNA reads CAA and liver genomic DNA also reads CAA. cDNA made from liver mRNA reads CAA, but cDNA made from intestinal mRNA reads TAA. Both mRNAs contain the same exons. What happened in the intestine?`,
    options: [r`A cytosine in the mRNA was deaminated to uracil`, r`A cytosine in the gene was mutated to thymine`, r`An exon carrying the CAA was skipped in splicing`, r`A uracil in the mRNA was methylated to thymine`],
    correctAnswer: 0,
    explanation: r`The DNA is the same in both tissues, so the change arose after transcription: an editing deaminase converted C to U in the mRNA, turning CAA into the stop codon UAA, which reads as TAA in cDNA. A gene mutation would show in the genomic DNA. Both mRNAs have the same exons, and the original base was C, not U.`,
  },
  [r`B cells switch membrane IgM to secreted IgM using a different {{c1::polyadenylation}} site, dropping the exons that encode the {{c2::transmembrane}} anchor.`]: {
    question: r`A B cell makes membrane-bound IgM and later makes secreted IgM. Both heavy-chain mRNAs come from the same gene, promoter and start site and share their 5' exons, but they end at different 3' positions. What accounts for the switch?`,
    options: [r`An earlier poly(A) site is used, dropping the membrane anchor exons`, r`An earlier poly(A) site is used, dropping the signal peptide exon`, r`A later promoter is used, dropping the membrane anchor exons`, r`A DNA deletion is made, removing the membrane anchor exons`],
    correctAnswer: 0,
    explanation: r`Choosing a poly-A site that lies upstream of the last exons leaves out the exons for the transmembrane anchor, so the antibody is secreted. The signal peptide is encoded at the 5' end, which is shared by both forms. The stem says the promoter is the same, and no DNA change is needed.`,
  },
  [r`Fusing a candidate promoter to a reporter such as {{c1::luciferase or GFP}} works because the cell makes {{c2::none}} of that product on its own.`]: {
    question: r`A student proposes testing a liver promoter in liver cells by fusing it to the coding region of albumin, a protein those cells already make in large amounts, and measuring total albumin. What is the main flaw compared with a luciferase reporter?`,
    options: [r`The cells' own promoter would silence the new plasmid`, r`The cells' own albumin would mask the reporter signal`, r`The albumin coding region cannot be transcribed`, r`The albumin protein would alter the promoter's DNA`],
    correctAnswer: 1,
    explanation: r`A reporter works because the cell makes none of it on its own, so every unit of signal comes from the attached regulatory DNA. Liver cells already make albumin, so the output of the test promoter could not be separated from the background. Albumin's coding region is transcribed normally and does not change DNA or silence plasmids.`,
  },
  [r`In a gel shift assay, labeled DNA migrates more slowly once nuclear extract is added. What is concluded, and what does adding antibody do?`]: {
    question: r`In a gel shift assay, a labeled probe alone runs fast. With nuclear extract it runs as a slower band. Adding an antibody to factor Y makes that band run even more slowly, while an antibody to factor W changes nothing. What is concluded?`,
    options: [r`Factor Y is part of the complex on the probe`, r`Factor W is part of the complex on the probe`, r`Factor Y digests the probe in the extract`, r`Neither factor binds; antibody binds DNA`],
    correctAnswer: 0,
    explanation: r`The slower band shows that an extract protein binds the probe, and an antibody that makes the complex bulkier still (a supershift) identifies its target as part of that complex. The antibody to W has no effect, so W is not there. Digestion would make faster fragments, and antibody binding DNA directly would shift the band with both antibodies.`,
  },
  [r`Chromatin immunoprecipitation enriches one promoter fragment 50-fold. What does that show that a gel shift cannot?`]: {
    question: r`Factor T shifts a promoter probe in gel shift assays using extract from either liver or kidney. Chromatin immunoprecipitation with an anti-T antibody enriches that promoter 50-fold from liver cells and not at all from kidney cells. What does the ChIP result add?`,
    options: [r`T occupies the promoter in liver chromatin only`, r`T is expressed as a protein in liver cells only`, r`T has a different binding sequence in each tissue`, r`T is proven to activate the gene in liver only`],
    correctAnswer: 0,
    explanation: r`ChIP reports where a factor actually sits in the chromatin of living cells, so it shows occupancy in liver and not in kidney. The gel shift only showed that T from either tissue can bind naked DNA, which also means T is present in both. Occupancy by itself does not prove that T activates the gene.`,
  },
}
